    def validate_document(name: str, value: Any, root: Path | None = None) -> None:
        if isinstance(value, dict):
            if name == "experiment_plan" and value.get("kind") == "pc01_diagnostic_plan":
                name = "pc01_plan"
            elif name == "experiment_result" and value.get("kind") == "pc01_diagnostic_result":
                name = "pc01_result"
        schema = load_schema(name, root)
        # Legacy schema bytes stay immutable. Versioned plan/result identity is
        # explicit; v3 metadata completeness is separately enforced by the runner.
        if name in ("pc01_plan", "pc01_result") and isinstance(value, dict):
